/// Zasady z `content/rules.toml`.
pub(crate) fn rules() -> RulesConfig {
    RulesConfig {
        duel: DuelRules {
            rounds: 5,
            attacks_per_round: 3,
            focus_per_round: 4,
            focus_cap: None,
            change_cost: 1,
            hand_size: 5,
            combo_multipliers: [1, 2, 4],
            block_min_stamina: 1,
            default_settings: DefaultSettings::HighestStat,
            counter_resolution: CounterResolution::InitiativeFirst,
            move_timeout_after_opponent_s: 60,
            round_timeout_s: 90,
            max_consecutive_timeouts: 3,
            reconnect_grace_s: 60,
        },
        deck: DeckRules {
            size: 20,
            max_copies: 4,
            fill_missing_with_random: true,
            saved_presets_max: 10,
        },
    }
}

